  async createKnowledgeProcessingJob({ userId, sourceId, jobType, request, idempotencyKey, maxAttempts = 3 }) { const id = randomUUID(); const client = await this.pool.connect(); try { await client.query('BEGIN'); const source = await client.query('SELECT id FROM knowledge_sources WHERE id = $1 AND user_id = $2 FOR UPDATE', [sourceId, userId]); if (!source.rows[0]) { await client.query('ROLLBACK'); return undefined; } if (jobType !== 'vector_delete') { const active = await client.query("SELECT * FROM knowledge_processing_jobs WHERE source_id = $1 AND user_id = $2 AND job_type <> 'vector_delete' AND status IN ('queued','leased','running') ORDER BY created_at DESC LIMIT 1 FOR UPDATE", [sourceId, userId]); if (active.rows[0]) { await client.query('COMMIT'); return active.rows[0]; } } const result = await client.query("INSERT INTO knowledge_processing_jobs (id,source_id,user_id,job_type,status,idempotency_key,request,max_attempts) VALUES ($1,$2,$3,$4,'queued',$5,$6::jsonb,$7) ON CONFLICT (source_id,job_type,idempotency_key) DO UPDATE SET updated_at = NOW() RETURNING *", [id, sourceId, userId, jobType, idempotencyKey, JSON.stringify(request || {}), Math.max(1, Math.min(8, maxAttempts))]); if (jobType !== 'vector_delete') await client.query("UPDATE knowledge_sources SET status = 'queued', updated_at = NOW() WHERE id = $1 AND user_id = $2 AND deleted_at IS NULL", [sourceId, userId]); await client.query('COMMIT'); return result.rows[0]; } catch (error) { await client.query('ROLLBACK').catch(() => undefined); throw error; } finally { client.release(); } },
