  async sharedConversationByTokenHash(tokenHash, { after = -1, limit = 100 } = {}) { const client = await this.pool.connect(); let began = false; try { await client.query('BEGIN'); began = true; const result = await client.query("SELECT * FROM conversation_share_links WHERE token_hash = $1 AND revoked_at IS NULL AND expires_at > NOW() FOR UPDATE", [tokenHash]); const row = result.rows[0]; if (!row) { await client.query('ROLLBACK'); began = false; return undefined; } const count = Number(row.message_count || 0); if (!count) { await client.query('ROLLBACK'); began = false; return undefined; } const cursor = Math.max(-1, Number(after) || -1); const pageSize = Math.max(1, Math.min(200, Number(limit) || 100)); const messages = await client.query('SELECT message_id,role,content,created_at,ordinal FROM conversation_share_messages WHERE share_id = $1 AND ordinal > $2 ORDER BY ordinal ASC LIMIT $3', [row.id, cursor, pageSize]); if (!messages.rows.length) { await client.query('ROLLBACK'); began = false; return undefined; } await client.query('UPDATE conversation_share_links SET last_accessed_at = NOW(), access_count = access_count + 1 WHERE id = $1 AND revoked_at IS NULL AND expires_at > NOW()', [row.id]); await client.query('COMMIT'); began = false; const lastOrdinal = Number(messages.rows[messages.rows.length - 1].ordinal); return { share: shareRow(row), title: row.title, messageCount: count, nextCursor: lastOrdinal < count - 1 ? lastOrdinal : undefined, messages: messages.rows.map(item => ({ id: item.message_id, role: item.role, content: item.content, createdAt: item.created_at })) }; } catch (error) { if (began) await client.query('ROLLBACK').catch(() => undefined); throw error; } finally { client.release(); } },
  async createApiKey({ userId, name, description, keyIdentifier, secretHash, scopes, expiresAt, maxActiveKeys }) {
    const client = await this.pool.connect(); let began = false;
    try {
      await client.query('BEGIN'); began = true;
      // Serialize key-count decisions per owner without imposing a commercial quota. This is a
      // bounded abuse/storage safeguard configured by the operator.
      await client.query('SELECT pg_advisory_xact_lock(hashtext($1))', [userId]);
      const active = await client.query("SELECT COUNT(*)::int AS count FROM api_keys WHERE user_id = $1 AND revoked_at IS NULL AND COALESCE(expires_at, NOW() + INTERVAL '100 years') > NOW()", [userId]);
      if (Number(active.rows[0]?.count || 0) >= maxActiveKeys) { await client.query('ROLLBACK'); began = false; return { limitReached: true }; }
      const id = randomUUID(); const created = await client.query('INSERT INTO api_keys (id,user_id,name,description,key_identifier,secret_hash,scopes,expires_at) VALUES ($1,$2,$3,$4,$5,$6,$7::jsonb,$8) RETURNING *', [id, userId, name, description || null, keyIdentifier, secretHash, JSON.stringify(scopes), expiresAt || null]);
      await client.query("INSERT INTO api_key_audit_events (id,api_key_id,user_id,actor_user_id,action,outcome,metadata) VALUES ($1,$2,$3,$3,'created','success',$4::jsonb)", [randomUUID(), id, userId, JSON.stringify({ scopes, expiresAt: expiresAt ? new Date(expiresAt).toISOString() : undefined })]);
      await client.query('COMMIT'); began = false; return { key: apiKeyRow(created.rows[0]) };
    } catch (error) { if (began) await client.query('ROLLBACK').catch(() => undefined); throw error; } finally { client.release(); }
  },
