      await client.query("INSERT INTO api_key_audit_events (id,api_key_id,user_id,actor_user_id,action,outcome,metadata) VALUES ($1,$2,$3,$3,'revoked','success','{}'::jsonb)", [randomUUID(), row.id, userId]); await client.query('COMMIT'); began = false; return apiKeyRow(row);
